package com.globalisosecurity.backend.services;

import com.globalisosecurity.backend.dto.ReporteResumenDTO;
import com.globalisosecurity.backend.models.*;
import com.globalisosecurity.backend.repositories.*;
import java.util.*;
import java.util.stream.Collectors;
import org.springframework.stereotype.Service;

@Service
public class ReporteService {
    private final ServicioRepository servicioRepository; private final EvaluacionRepository evaluacionRepository; private final FirmaRepository firmaRepository; private final CapacitacionRepository capacitacionRepository; private final SoaControlRepository soaRepository; private final RiesgoRepository riesgoRepository; private final RiesgoControlRepository riesgoControlRepository; private final EvidenciaRepository evidenciaRepository; private final RpmAnalisisRepository rpmRepository; private final RpmDecisionRepository decisionRepository; private final AccesoEmpresaService acceso; private final SoaService soaService;
    public ReporteService(ServicioRepository servicioRepository,EvaluacionRepository evaluacionRepository,FirmaRepository firmaRepository,CapacitacionRepository capacitacionRepository,SoaControlRepository soaRepository,RiesgoRepository riesgoRepository,RiesgoControlRepository riesgoControlRepository,EvidenciaRepository evidenciaRepository,RpmAnalisisRepository rpmRepository,RpmDecisionRepository decisionRepository,AccesoEmpresaService acceso,SoaService soaService){this.servicioRepository=servicioRepository;this.evaluacionRepository=evaluacionRepository;this.firmaRepository=firmaRepository;this.capacitacionRepository=capacitacionRepository;this.soaRepository=soaRepository;this.riesgoRepository=riesgoRepository;this.riesgoControlRepository=riesgoControlRepository;this.evidenciaRepository=evidenciaRepository;this.rpmRepository=rpmRepository;this.decisionRepository=decisionRepository;this.acceso=acceso;this.soaService=soaService;}
    public ReporteResumenDTO obtenerReportePorEmpresa(Long empresaId){acceso.validarEmpresa(empresaId);List<Servicio> servicios=servicioRepository.findByEmpresaId(empresaId);ReporteResumenDTO r=new ReporteResumenDTO();r.setEmpresaId(empresaId);r.setTotalServicios(servicios.size());r.setTotalEvaluaciones(evaluacionRepository.findByServicioEmpresaId(empresaId).size());r.setTotalFirmas(firmaRepository.findByServicioEmpresaId(empresaId).size());r.setTotalCapacitaciones(capacitacionRepository.findByServicioEmpresaId(empresaId).size());r.setEstadosServicios(servicios.stream().map(Servicio::getEstado).toList());if(servicios.isEmpty()){r.setSoa(List.of());r.setRiesgos(List.of());r.setRpm(List.of());return r;}Servicio s=servicioRepository.findFirstByEmpresaIdOrderByFechaCreacionDesc(empresaId).orElse(servicios.get(0));if(soaRepository.countByServicioId(s.getId())==0)soaService.inicializar(s.getId());r.setEmpresaNombre(s.getEmpresa().getNombre());r.setServicioId(s.getId());r.setSector(s.getSector()!=null?s.getSector().getNombre():"");r.setEstadoServicio(s.getEstado());List<SoaControl> soa=soaRepository.findByServicioIdOrderByControlCodigoAsc(s.getId());r.setTotalControles(soa.size());r.setControlesAplicables((int)soa.stream().filter(x->"APLICABLE".equals(x.getAplicabilidad())).count());r.setControlesNoAplicables((int)soa.stream().filter(x->"NO_APLICABLE".equals(x.getAplicabilidad())).count());r.setControlesPendientes(r.getTotalControles()-r.getControlesAplicables()-r.getControlesNoAplicables());r.setControlesImplementados((int)soa.stream().filter(x->"IMPLEMENTADO".equals(x.getEstadoImplementacion())).count());r.setPorcentajeImplementacion(r.getControlesAplicables()==0?0:(int)Math.round(soa.stream().filter(x->"APLICABLE".equals(x.getAplicabilidad())).mapToInt(SoaControl::getPorcentajeImplementacion).average().orElse(0)));r.setSoa(soa.stream().map(x->new ReporteResumenDTO.SoaFila(x.getControl().getCodigo(),x.getControl().getTitulo(),x.getControl().getDominio(),x.getAplicabilidad(),safe(x.getJustificacionAplicabilidad()),x.getEstadoImplementacion(),x.getPorcentajeImplementacion(),safe(x.getResponsable()),x.getFechaObjetivo()==null?"":x.getFechaObjetivo().toString(),evidenciaRepository.findBySoaControlIdOrderByFechaCargaDesc(x.getId()).size(),riesgoControlRepository.findByControlIdAndRiesgoServicioId(x.getControl().getId(),s.getId()).size())).toList());List<Riesgo> riesgos=riesgoRepository.findByServicioIdOrderByNivelInherenteDesc(s.getId());r.setTotalRiesgos(riesgos.size());r.setRiesgosCriticos((int)riesgos.stream().filter(x->"CRITICO".equals(RiesgoService.categoria(x.getNivelInherente()))).count());r.setRiesgosAltos((int)riesgos.stream().filter(x->"ALTO".equals(RiesgoService.categoria(x.getNivelInherente()))).count());r.setRiesgos(riesgos.stream().map(x->new ReporteResumenDTO.RiesgoFila(x.getCodigo(),x.getNombre(),safe(x.getActivoInformacion()),x.getProbabilidad(),x.getImpacto(),x.getNivelInherente(),RiesgoService.categoria(x.getNivelInherente()),x.getTratamiento(),x.getEstado(),riesgoControlRepository.findByRiesgoId(x.getId()).stream().map(y->y.getControl().getCodigo()).collect(Collectors.joining(", ")))).toList());List<Evidencia> ev=evidenciaRepository.findByServicioIdOrderByFechaCargaDesc(s.getId());r.setEvidenciasValidadas((int)ev.stream().filter(x->"VALIDADA".equals(x.getEstado())).count());r.setEvidenciasPendientes((int)ev.stream().filter(x->"PENDIENTE".equals(x.getEstado())).count());r.setEvidenciasRechazadas((int)ev.stream().filter(x->"RECHAZADA".equals(x.getEstado())).count());Map<Long,RpmAnalisis> latest=new LinkedHashMap<>();for(RpmAnalisis a:rpmRepository.findByServicioIdOrderByGeneradoEnDesc(s.getId()))latest.putIfAbsent(a.getSoaControl()!=null?a.getSoaControl().getId():-a.getId(),a);List<RpmAnalisis> rpm=new ArrayList<>(latest.values());r.setAlertasRpm((int)rpm.stream().filter(x->Set.of("ALTA","CRITICA").contains(x.getPrioridad())).count());r.setRpm(rpm.stream().map(x->new ReporteResumenDTO.RpmFila(x.getSoaControl()!=null?x.getSoaControl().getControl().getCodigo():"",x.getPrioridad(),x.getPuntaje(),x.getPrioridadMl(),x.getConfianzaMl(),x.getVersionModeloMl(),x.getEstado(),x.getResumen(),decisionRepository.findByAnalisisId(x.getId()).stream().map(RpmDecision::getAccion).collect(Collectors.joining(" | ")))).toList());return r;}
    private String safe(String s){return s==null?"":s;}
}
